CREATE ROLE app NOLOGIN;
CREATE ROLE invoice_purge_owner NOLOGIN;

CREATE TABLE accounts (id text PRIMARY KEY, is_demo boolean NOT NULL);
CREATE TABLE orders (id text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts(id), state text NOT NULL DEFAULT 'NEW');
CREATE TABLE invoice_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT);

CREATE FUNCTION reject_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_user = 'invoice_purge_owner' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'invoice audit is immutable';
END $$;
CREATE TRIGGER invoice_audit_immutable BEFORE UPDATE OR DELETE ON invoice_audit
  FOR EACH ROW EXECUTE FUNCTION reject_audit_change();
CREATE TRIGGER invoice_audit_no_truncate BEFORE TRUNCATE ON invoice_audit
  FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_change();

CREATE FUNCTION complete_order(order_id text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO invoice_audit(order_id) VALUES (complete_order.order_id);
  UPDATE orders SET state = 'DONE' WHERE id = complete_order.order_id;
END $$;

CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  unhandled record;
BEGIN
  -- Lock the account so its demo status cannot change during the purge.
  PERFORM 1 FROM public.accounts a
    WHERE a.id = purge_demo_account.account_id AND a.is_demo FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Refuse to proceed if a new restrictive relationship has not been
  -- explicitly incorporated into this routine's deletion order.
  SELECT c.conname, c.conrelid::regclass AS relation INTO unhandled
  FROM pg_catalog.pg_constraint c
  WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r')
    AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass, 'public.invoice_audit'::regclass)
    AND NOT (c.conrelid = 'public.orders'::regclass AND c.confrelid = 'public.accounts'::regclass
             AND c.conkey = ARRAY[(SELECT attnum FROM pg_catalog.pg_attribute WHERE attrelid = 'public.orders'::regclass AND attname = 'account_id')]::smallint[]
             AND c.confkey = ARRAY[(SELECT attnum FROM pg_catalog.pg_attribute WHERE attrelid = 'public.accounts'::regclass AND attname = 'id')]::smallint[])
    AND NOT (c.conrelid = 'public.invoice_audit'::regclass AND c.confrelid = 'public.orders'::regclass
             AND c.conkey = ARRAY[(SELECT attnum FROM pg_catalog.pg_attribute WHERE attrelid = 'public.invoice_audit'::regclass AND attname = 'order_id')]::smallint[]
             AND c.confkey = ARRAY[(SELECT attnum FROM pg_catalog.pg_attribute WHERE attrelid = 'public.orders'::regclass AND attname = 'id')]::smallint[])
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'unhandled foreign key % on %', unhandled.conname, unhandled.relation USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.invoice_audit ia USING public.orders o
    WHERE ia.order_id = o.id AND o.account_id = purge_demo_account.account_id;
  DELETE FROM public.orders o WHERE o.account_id = purge_demo_account.account_id;
  DELETE FROM public.accounts a WHERE a.id = purge_demo_account.account_id AND a.is_demo;
END $$;

GRANT SELECT, INSERT, UPDATE, DELETE ON accounts, orders TO app;
GRANT SELECT, INSERT ON invoice_audit TO app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO app;
GRANT USAGE ON SCHEMA public TO invoice_purge_owner;
GRANT SELECT, DELETE ON accounts, orders, invoice_audit TO invoice_purge_owner;
-- SELECT FOR UPDATE requires UPDATE privilege on at least one column.
GRANT UPDATE (is_demo) ON accounts TO invoice_purge_owner;
ALTER FUNCTION purge_demo_account(text) OWNER TO invoice_purge_owner;
